-- =====================================================================
-- Ride Assure v2: nightly auto-refresh for the simulated AAR data.
-- Generated by supabase/generate_seed.py. Run ONCE, after schema.sql.
--
-- Creates reset_demo(), which reloads all the fake data with today's dates
-- (and clears yesterday's demo calls), and schedules it every day at
-- 08:00 UTC (4 am New York time in summer, 3 am in winter).
--
-- Run it by hand any time:   select reset_demo();
-- Stop the nightly refresh:  select cron.unschedule('ride-assure-nightly-reset');
-- =====================================================================

-- New York local time, N days ago, plus M minutes.
create or replace function demo_ts(days_ago int, hhmm text, plus_min int default 0)
returns timestamptz language sql stable as $$
  select ((((now() at time zone 'America/New_York')::date - days_ago) + hhmm::time)
    at time zone 'America/New_York') + make_interval(mins => plus_min) $$;

create or replace function reset_demo() returns void
language plpgsql security definer set search_path = public as $fn$
