-- Only the database itself (and you, in the SQL Editor) may run these.
-- The browser must never be able to wipe the demo.
revoke execute on function reset_demo() from public, anon, authenticated;
revoke execute on function demo_ts(int, text, int) from public, anon, authenticated;

-- Schedule it nightly.
create extension if not exists pg_cron;
select cron.schedule('ride-assure-nightly-reset', '0 8 * * *', 'select public.reset_demo()');

-- Refresh right now too, so today's data is current.
select reset_demo();
