insert into faq (topic, question, answer) values
  ('pickup_window', 'How long should I wait for my ride?', 'Your pickup window is 30 minutes. It starts at your scheduled pickup time and ends 30 minutes later. Please be ready at the start of the window.'),
  ('driver_wait', 'How long will the driver wait for me?', 'The driver must wait five minutes after your scheduled pickup time, even if they arrive early.'),
  ('late_vehicle', 'My ride is late. What can I do?', 'I can check where your van is right now. If it is going to arrive more than 30 minutes after your scheduled pickup time, I can try to arrange other transportation for you.'),
  ('door_assist', 'Will the driver help me?', 'Drivers assist riders in boarding and exiting the vehicle safely. I can ask the vendor to have the driver call you or come to the door.'),
  ('trip_id', 'What is a Trip ID?', 'Each trip has its own Trip ID number. It helps me find that trip quickly when you call about it.'),
  ('aar_id', 'Why do you need my AAR ID?', 'Your AAR ID and date of birth let me confirm I am speaking about the right account. I can''t look up an account by name.'),
  ('complaint', 'How do I file a complaint?', 'I can record a complaint on this call. I will need the date, the Trip ID if you have it, and what happened. I will give you a complaint number.'),
  ('booking', 'Can you book or change a trip?', 'This demo line handles trip status, driver call-outs, and complaints. Booking and changes are not part of this simulation.'),
  ('caregiver', 'Can I call for my mother?', 'Yes. I will need her AAR ID and date of birth, and I will note that you are calling on her behalf.');
